    22	// Percentages are kept as exact fractions (integer numerator over PERCENT);
    23	// scaling by a float rate such as 0.1 yields artefacts like 115.00000000000001.
    24	function percentOf(amount: number, percent: number): number {
    25	  return (amount * percent) / PERCENT;
    26	}
