   139	/**
   140	 * The discount is offered on "each contract after their first", so any contract
   141	 * preceded by at least one earlier one qualifies -- the very first does not.
   142	 */
   143	function isFollowUpContract(previousContracts: number): boolean {
   144	  return previousContracts > 0;
   145	}
   146	
   147	/**
   148	 * Policy-wide modifiers are all charged against the policy base premium, so the
   149	 * MHPCO nets them into a single percentage: a long-standing customer earns a
   150	 * loyalty discount, a follow-up contract earns its own discount, and every
   151	 * quoted policy carries the first-insurance assessment.
   152	 *
   153	 * The assessment is deliberately unconditional -- it is not a missing check on
   154	 * customer history. The MHPCO treats each item in a quote as a first insurance
   155	 * regardless of how long the customer has been with the office, so even a
   156	 * long-standing customer's follow-up contract still carries the 10 %.
   157	 */
   158	function policyWideModifierPercent(customer: Customer, previousContracts: number): number {
   159	  const loyaltyPercent = isLongStanding(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0;
   160	  const followUpPercent = isFollowUpContract(previousContracts) ? -FOLLOW_UP_DISCOUNT_PERCENT : 0;
   161	  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyaltyPercent + followUpPercent;
   162	}
