     1	/**
     2	 * The MHPCO claim office: it settles a damage report against an open policy. It
     3	 * answers what the office pays for a reported damage -- what the damage is worth
     4	 * under the policy's clauses, and what the office's settlement conventions then
     5	 * deduct from it. It knows nothing about what a policy costs to take out; that
     6	 * is the quote's business.
     7	 */
     8	
     9	import { insuranceValueOf, type Item } from "./price-list.js";
    10	
    11	export interface Damage {
    12	  itemType: string;
    13	  amount: number;
    14	}
    15	
    16	export interface Incident {
    17	  cause: string;
    18	  damages: Damage[];
    19	}
    20	
    21	export interface Policy {
    22	  items: Item[];
    23	  cap: number;
    24	  /** What is left of the cap after the claims already paid on this policy. */
    25	  remainingCap: number;
    26	}
    27	
    28	export interface ClaimResult {
    29	  payout: number;
    30	  remainingCap: number;
    31	}
    32	
    33	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    34	
    35	/** The sum a policy insures, read off the price list for the items it covers. */
    36	export function insuranceSum(policy: Policy): number {
    37	  return insuranceValueOf(policy.items);
    38	}
    39	
    40	/**
    41	 * Opening a policy fixes the cover it grants: the office caps its total payout at
    42	 * twice the insurance sum of the items presented. The cap is fixed from the
    43	 * items' own insurance values, so no premium modifier can raise it.
    44	 */
    45	export function openPolicy(items: Item[]): Policy {
    46	  const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceValueOf(items);
    47	  return { items, cap, remainingCap: cap };
    48	}
    49	
    50	const DEDUCTIBLE_PER_DAMAGE = 100;
    51	
    52	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
    53	const HALF_REIMBURSEMENT_PERCENT = 50;
    54	const PERCENT = 100;
    55	
    56	/**
    57	 * The claim office's enchantment threshold, deliberately its own rule. The price
    58	 * list also reads an enchantment level off an item, but for an unrelated purpose
    59	 * and at an unrelated level (>= 5, a premium risk surcharge). The two thresholds
    60	 * share no cause: moving one does not move the other, which is why the office
    61	 * keeps them apart rather than naming them alike.
    62	 */
    63	function qualifiesForHalfReimbursement(item: Item): boolean {
    64	  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
    65	}
    66	
    67	/**
    68	 * What a reported damage is worth under the policy's clauses. A deeply enchanted
    69	 * item is reimbursed at half its damage; an item no clause speaks to is
    70	 * reimbursed in full.
    71	 *
    72	 * The office also names a dragon-material clause, and it is deliberately absent
    73	 * here rather than overlooked. That clause grants full reimbursement -- which is
    74	 * already what an item no clause speaks to receives -- so it can only change an
    75	 * outcome by overriding a *reducing* clause. Against the sole reducing clause the
    76	 * office has, the half-reimbursement rule, it does not: a dragon-material sword
    77	 * at enchantment 8 or 9 is valued at half, not in full. So under every rule the
    78	 * office currently holds, a dragon branch would return exactly what this fallback
    79	 * returns. Writing it would not encode the clause; it would encode a precedence
    80	 * decision between dragon material and some future reducing clause, and the
    81	 * office has not made that decision. When a reducing clause appears that dragon
    82	 * material is meant to outrank, that precedence becomes observable and belongs
    83	 * here then.
    84	 */
    85	function reimbursementFor(damage: Damage, item: Item): number {
    86	  if (qualifiesForHalfReimbursement(item)) {
    87	    return (damage.amount * HALF_REIMBURSEMENT_PERCENT) / PERCENT;
    88	  }
    89	  return damage.amount;
    90	}
    91	
    92	/** The insured item a reported damage refers to, found by its type. */
    93	function damagedItem(policy: Policy, damage: Damage): Item {
    94	  const item = policy.items.find((insured) => insured.type === damage.itemType);
    95	  if (item === undefined) {
    96	    throw new Error(`The policy does not cover an item of type "${damage.itemType}"`);
    97	  }
    98	  return item;
    99	}
   100	
   101	/**
   102	 * Settling turns a reimbursement into the sum actually paid. The deductible is
   103	 * the MHPCO's settlement convention, not a clause: it is charged per damage
   104	 * event, after the reimbursement is valued, and never turns a payout negative.
   105	 */
   106	function settleReimbursement(reimbursement: number): number {
   107	  return Math.max(reimbursement - DEDUCTIBLE_PER_DAMAGE, 0);
   108	}
   109	
   110	/**
   111	 * The office's whole decision about one reported damage: find the item it refers
   112	 * to, value it under the policy's clauses, then settle that reimbursement. What
   113	 * the office then does with several such sums -- adding them up, and one day
   114	 * charging them against the policy's remaining cap -- is the claim's business,
   115	 * not this one's.
   116	 */
   117	function settleDamage(policy: Policy, damage: Damage): number {
   118	  return settleReimbursement(reimbursementFor(damage, damagedItem(policy, damage)));
   119	}
   120	
   121	/**
   122	 * What the office would pay for an incident on the strength of its damages
   123	 * alone: every reported damage settled under the policy's clauses, added up.
   124	 * This is what the claim *desires* to pay -- a separate question from what the
   125	 * policy's remaining cover then permits it to actually pay.
   126	 */
   127	function desiredPayout(policy: Policy, incident: Incident): number {
   128	  return incident.damages.reduce((total, damage) => total + settleDamage(policy, damage), 0);
   129	}
   130	
   131	/**
   132	 * The cover side of the office's ledger, the counterpart of `openPolicy`: what
   133	 * the policy actually permits the office to pay towards a desired sum, and what
   134	 * that leaves. A claim may draw no more than the cover still standing, so a
   135	 * desire that would exceed it is reduced to whatever remains; what is drawn is
   136	 * then gone from the policy for good.
   137	 *
   138	 * This is where the office's cap rule is revised -- a per-incident sub-cap or a
   139	 * cover that reinstates would change this line and `openPolicy`, and nothing
   140	 * about how a damage is valued or settled.
   141	 */
   142	function drawDownCover(policy: Policy, desired: number): number {
   143	  const drawn = Math.min(desired, policy.remainingCap);
   144	  policy.remainingCap -= drawn;
   145	  return drawn;
   146	}
   147	
   148	/**
   149	 * The office pays what the incident's damages come to, so far as the policy's
   150	 * remaining cover permits.
   151	 */
   152	export function claim(policy: Policy, incident: Incident): ClaimResult {
   153	  const payout = drawDownCover(policy, desiredPayout(policy, incident));
   154	  return { payout, remainingCap: policy.remainingCap };
   155	}

